package com.bank.tools;

// Describes a build: its coverage, code issues, and dependency CVEs.
public class BuildArtifact {
    private final String name;
    private final double coverage;        // 0..1 test coverage on new code
    private final int criticalIssues;     // Sonar critical issues
    private final int highCriticalCves;   // Trivy/Grype high+critical CVEs
    private final boolean sqlConcatInCode; // SAST signal
    private final boolean authBypassAtRuntime; // DAST signal

    public BuildArtifact(String name, double coverage, int criticalIssues,
                         int highCriticalCves, boolean sqlConcatInCode,
                         boolean authBypassAtRuntime) {
        this.name = name;
        this.coverage = coverage;
        this.criticalIssues = criticalIssues;
        this.highCriticalCves = highCriticalCves;
        this.sqlConcatInCode = sqlConcatInCode;
        this.authBypassAtRuntime = authBypassAtRuntime;
    }
    public String getName()              { return name; }
    public double getCoverage()          { return coverage; }
    public int getCriticalIssues()       { return criticalIssues; }
    public int getHighCriticalCves()     { return highCriticalCves; }
    public boolean hasSqlConcat()        { return sqlConcatInCode; }
    public boolean hasAuthBypass()       { return authBypassAtRuntime; }
}
