package com.bank.tools;

import java.util.logging.Logger;

// SonarQube role: fail the build on low coverage or critical issues.
public class QualityGate {
    private static final Logger log = Logger.getLogger(QualityGate.class.getName());
    private static final double MIN_COVERAGE = 0.80;

    public boolean passes(BuildArtifact a) {
        log.info(() -> "SonarQube: coverage=" + (a.getCoverage() * 100) + "% critical="
                + a.getCriticalIssues());
        if (a.getCoverage() < MIN_COVERAGE) {
            log.severe("Quality gate FAILED: coverage below 80% on new code");
            return false;
        }
        if (a.getCriticalIssues() > 0) {
            log.severe("Quality gate FAILED: " + a.getCriticalIssues() + " new critical issues");
            return false;
        }
        log.info("Quality gate PASSED");
        return true;
    }
}
