package com.bank.tools;

import java.util.logging.Logger;

// Trivy/Grype role: fail the build on HIGH/CRITICAL CVEs.
public class VulnerabilityScanner {
    private static final Logger log = Logger.getLogger(VulnerabilityScanner.class.getName());

    public boolean passes(BuildArtifact a) {
        log.info(() -> "Trivy: scanning " + a.getName() + " -> high/critical CVEs="
                + a.getHighCriticalCves());
        if (a.getHighCriticalCves() > 0) {
            log.severe("Image scan FAILED: " + a.getHighCriticalCves() + " HIGH/CRITICAL CVEs");
            return false;
        }
        log.info("Image scan PASSED (no high/critical CVEs)");
        return true;
    }
}
