package com.bank.tools;

import java.util.logging.Logger;

// SAST analyses code (no run); DAST attacks the running app.
public class SecurityScan {
    private static final Logger log = Logger.getLogger(SecurityScan.class.getName());

    public boolean sast(BuildArtifact a) {
        log.info(() -> "SAST: static analysis of source/bytecode for " + a.getName());
        if (a.hasSqlConcat()) {
            log.severe("SAST FAILED: SQL built by string concatenation (injection risk)");
            return false;
        }
        log.info("SAST PASSED");
        return true;
    }

    public boolean dast(BuildArtifact a) {
        log.info(() -> "DAST: sending requests to the RUNNING " + a.getName());
        if (a.hasAuthBypass()) {
            log.severe("DAST FAILED: authentication bypass reachable at runtime");
            return false;
        }
        log.info("DAST PASSED");
        return true;
    }
}
