package com.bank.tools;

import java.util.*;
import java.util.logging.Logger;

// Nexus/Artifactory role: store ONLY artifacts that passed all gates.
public class ArtifactRepository {
    private static final Logger log = Logger.getLogger(ArtifactRepository.class.getName());
    private final Map<String, String> store = new HashMap<>();

    public void publish(String name, String version) {
        String coord = name + ":" + version;
        store.put(coord, "stored");
        log.info(() -> "Published to Nexus: " + coord);
    }

    public boolean contains(String coord) { return store.containsKey(coord); }
}
