// ─── File: src/main/java/com/bank/tools/CicdToolsDemo.java ───
package com.bank.tools;

import java.util.logging.*;

public class CicdToolsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CicdToolsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        QualityGate gate = new QualityGate();
        VulnerabilityScanner scanner = new VulnerabilityScanner();
        SecurityScan security = new SecurityScan();
        ArtifactRepository repo = new ArtifactRepository();

        // 1) Low coverage -> blocked by SonarQube.
        run(gate, scanner, security, repo,
            new BuildArtifact("transfer-service:A", 0.55, 0, 0, false, false));

        // 2) Critical CVE -> blocked by Trivy.
        run(gate, scanner, security, repo,
            new BuildArtifact("transfer-service:B", 0.90, 0, 3, false, false));

        // 3) Clean -> passes everything and is published.
        run(gate, scanner, security, repo,
            new BuildArtifact("transfer-service:C", 0.90, 0, 0, false, false));
    }

    static void run(QualityGate gate, VulnerabilityScanner scanner, SecurityScan security,
                    ArtifactRepository repo, BuildArtifact a) {
        Logger log = Logger.getLogger(CicdToolsDemo.class.getName());
        log.info("=== Pipeline for " + a.getName() + " ===");
        if (!gate.passes(a))        { log.severe("BLOCKED at quality gate"); return; }
        if (!scanner.passes(a))     { log.severe("BLOCKED at vulnerability scan"); return; }
        if (!security.sast(a))      { log.severe("BLOCKED at SAST"); return; }
        String[] parts = a.getName().split(":");
        repo.publish(parts[0], parts[1]);         // only now is it publishable
        if (!security.dast(a))      { log.severe("DAST failed after deploy to test env"); return; }
        log.info(a.getName() + " passed all gates and DAST");
    }
}

// ─── Would be in CicdToolsLogFormatter.java in a real project ───
class CicdToolsLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
